  const tasks = [editTask, conceptTask, soundTask, musicTask]; const activeTask = tasks.find(item => item.loading) ?? tasks.find(item => item.error || item.canceled) ?? editTask
  const play = (pitch: number, velocity = .8, duration = .28, brightness = .55) => { const ctx = audio.current ?? (audio.current = new AudioContext()); if (ctx.state === 'suspended') void ctx.resume(); const now = ctx.currentTime; const gain = ctx.createGain(); const filter = ctx.createBiquadFilter(); const pan = ctx.createStereoPanner(); const main = ctx.createOscillator(); const air = ctx.createOscillator(); main.type = brightness < .34 ? 'sine' : brightness < .72 ? 'triangle' : 'sawtooth'; air.type = 'sine'; main.frequency.value = hz(pitch); air.frequency.value = hz(pitch) * 2; air.detune.value = 5; filter.type = 'lowpass'; filter.frequency.value = 750 + brightness * 4600; filter.Q.value = 1.5 + brightness * 3; pan.pan.value = brightness * 1.2 - .6; gain.gain.setValueAtTime(.0001, now); gain.gain.exponentialRampToValueAtTime(.075 * velocity, now + .012 + (1 - brightness) * .035); gain.gain.exponentialRampToValueAtTime(.0001, now + duration); main.connect(filter); air.connect(filter); filter.connect(gain).connect(pan).connect(ctx.destination); main.start(now); air.start(now); main.stop(now + duration + .04); air.stop(now + duration + .04) }
  const playChord = (pitches: number[], velocity = .8, duration = .28, brightness = .55) => { pitches.forEach((pitch, index) => play(pitch, velocity * (index === 0 ? 1 : .62), duration, Math.min(1, brightness + index * .025))) }
