  const triggerGesture = (e: React.PointerEvent<HTMLCanvasElement>, force = false) => { const el = canvas.current; if (!el || (!gesture.current.active && !force)) return; const r = el.getBoundingClientRect(); const x = Math.max(0, Math.min(r.width, e.clientX - r.left)); const y = Math.max(0, Math.min(r.height, e.clientY - r.top)); const nx = x / r.width; const ny = y / r.height; const now = performance.now(); const row = Math.max(0, Math.min(gestureScale.length - 1, Math.floor((1 - ny) * gestureScale.length))); const column = Math.max(0, Math.min(5, Math.floor(nx * 6))); const cell = `${row}:${column}`; const elapsed = Math.max(16, now - gesture.current.at); const distance = Math.hypot(x - gesture.current.x, y - gesture.current.y); cursor.current = { x, y, active: true }; if (!force && (cell === gesture.current.cell || now - gesture.current.at < 58)) return; const velocity = Math.max(.35, Math.min(1, .38 + distance / elapsed * .55)); const duration = .22 + nx * .28; const pitch = gestureScale[row]; const chord = chordPitches(pitch); gesture.current = { active: true, x, y, at: now, cell }; playChord(chord, velocity, duration, nx); const color = nx > .66 ? '#fb9ab0' : nx > .33 ? '#b9a7ff' : '#7dd3fc'; for (let i = 0; i < 3; i++) particles.current.push({ x: x + (Math.random() - .5) * 16, y: y + (Math.random() - .5) * 16, r: 2 + Math.random() * 5, life: 1, color }); if (recording) { const start = Math.min(9.8, Math.max(0, (now - recordingStarted.current) / 1000)); const chordNotes: Note[] = chord.map((chordPitch, index) => ({ id: `${now}-${row}-${column}-${index}`, pitch: chordPitch, start, duration, velocity: Math.round(velocity * 127 * (index === 0 ? 1 : .72)) })); setHistory(current => { const previous = currentProject(current); const target = primaryMelodyTrack(previous); const next = target ? { ...previous, tracks: previous.tracks.map(t => t.id === target.id ? { ...t, notes: [...(t.notes ?? []), ...chordNotes].slice(-96) } : t) } : { ...previous, tracks: [...previous.tracks, melodyTrackTemplate(chordNotes.slice(-96))] }; return pushHistory(current, next, '记录手势音符', { key: 'gesture-notes' }) }) } }
  const gestureStart = (e: React.PointerEvent<HTMLCanvasElement>) => { const r = e.currentTarget.getBoundingClientRect(); e.currentTarget.setPointerCapture(e.pointerId); gesture.current = { active: true, x: e.clientX - r.left, y: e.clientY - r.top, at: performance.now() - 100, cell: '' }; triggerGesture(e, true) }
  const gestureEnd = (e: React.PointerEvent<HTMLCanvasElement>) => { if (e.currentTarget.hasPointerCapture(e.pointerId)) e.currentTarget.releasePointerCapture(e.pointerId); gesture.current.active = false; gesture.current.cell = ''; cursor.current.active = false }
  useEffect(() => { const c = canvas.current; if (!c) return; const ctx = c.getContext('2d'); if (!ctx) return; const resize = () => { const r = c.getBoundingClientRect(); const d = devicePixelRatio || 1; c.width = r.width * d; c.height = r.height * d; ctx.setTransform(d, 0, 0, d, 0, 0) }; resize(); addEventListener('resize', resize); let frame = 0; const draw = () => { const r = c.getBoundingClientRect(); ctx.clearRect(0, 0, r.width, r.height); const g = ctx.createRadialGradient(r.width / 2, r.height / 2, 0, r.width / 2, r.height / 2, r.width * .65); g.addColorStop(0, 'rgba(84,88,190,.2)'); g.addColorStop(1, 'rgba(5,6,19,0)'); ctx.fillStyle = g; ctx.fillRect(0, 0, r.width, r.height); ctx.strokeStyle = 'rgba(185,192,255,.08)'; ctx.lineWidth = 1; for (let i = 1; i < gestureScale.length; i++) { const y = i / gestureScale.length * r.height; ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(r.width, y); ctx.stroke() } for (let i = 1; i < 6; i++) { const x = i / 6 * r.width; ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, r.height); ctx.stroke() } particles.current = particles.current.map(p => ({ ...p, y: preferences.reducedMotion ? p.y : p.y - .45, life: p.life - .018, r: p.r * .992 })).filter(p => p.life > 0); particles.current.forEach(p => { ctx.globalAlpha = p.life; ctx.fillStyle = p.color; ctx.shadowBlur = 18; ctx.shadowColor = p.color; ctx.beginPath(); ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2); ctx.fill() }); if (cursor.current.active) { ctx.globalAlpha = .9; ctx.strokeStyle = '#fff'; ctx.lineWidth = 1.5; ctx.beginPath(); ctx.arc(cursor.current.x, cursor.current.y, 12, 0, Math.PI * 2); ctx.stroke() } ctx.globalAlpha = 1; ctx.shadowBlur = 0; frame = requestAnimationFrame(draw) }; draw(); return () => { cancelAnimationFrame(frame); removeEventListener('resize', resize) } }, [preferences.reducedMotion])
